<?php
declare(strict_types=1);
require __DIR__.'/../app/services/PessoasService.php';
class ReI85Db extends PDO { public function prepare(string $sql,array $options=[]): PDOStatement|false {$sql=preg_replace('/ FOR UPDATE$/i','',$sql);return parent::prepare(preg_replace('/ LIMIT 1$/','',str_replace('NOW()',"'2026-01-01'",$sql)),$options);} }
function check85(bool $value,string $message): void { if (!$value) throw new RuntimeException($message); }
function db85(): PDO { $db=new ReI85Db('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$db->exec('CREATE TABLE partes (id TEXT PRIMARY KEY,cpf TEXT,nome_completo TEXT,sexo TEXT,data_nascimento TEXT,profissao TEXT,created_at TEXT,updated_at TEXT)');
$db->exec('CREATE TABLE instituicoes_publicas (id TEXT PRIMARY KEY,nome TEXT,nome_fantasia TEXT)');
$db->exec('CREATE TABLE partes_instituicoes (id TEXT PRIMARY KEY,parte_id TEXT,instituicao_id TEXT,setor_id TEXT,profissao TEXT,cargo_funcao TEXT,data_inclusao TEXT,data_inicio TEXT,data_fim TEXT,ativo INTEGER,observacoes TEXT,created_at TEXT,updated_at TEXT)');
$db->exec("INSERT INTO partes VALUES ('p',NULL,'Pessoa',NULL,NULL,NULL,'2026-01-01','2026-01-01')");$db->exec("INSERT INTO instituicoes_publicas VALUES ('i1','Instituicao 1',NULL),('i2','Instituicao 2',NULL)");return $db; }
function fail85(PDO $db):void {$db->exec("CREATE TRIGGER falha BEFORE UPDATE OF profissao ON partes BEGIN SELECT RAISE(ABORT,'falha sintetica'); END");}
function snapshot85(PDO $db):array{return [$db->query('SELECT * FROM partes ORDER BY id')->fetchAll(PDO::FETCH_ASSOC),$db->query('SELECT * FROM partes_instituicoes ORDER BY id')->fetchAll(PDO::FETCH_ASSOC)];}
foreach(['add','update','delete'] as $op){$db=db85(); if($op!=='add'){$db->exec("INSERT INTO partes_instituicoes VALUES ('v1','p','i1',NULL,NULL,NULL,'2026-01-01',NULL,NULL,1,NULL,'2026-01-01','2026-01-01')");if($op==='delete')$db->exec("INSERT INTO partes_instituicoes VALUES ('v2','p','i2',NULL,'Medico',NULL,'2026-01-02',NULL,NULL,1,NULL,'2026-01-02','2026-01-02')");}fail85($db);$before=snapshot85($db);$svc=new PessoasService($db);try {if($op==='add')$svc->addVinculoInstituicao('p',['instituicao_id'=>'i1','profissao'=>'Medico']);elseif($op==='update')$svc->updateVinculoInstituicao('v1',['profissao'=>'Medico']);else $svc->deleteVinculoInstituicao('v1');throw new RuntimeException('faltou falha '.$op);}catch(PDOException $e){check85(str_contains($e->getMessage(),'falha sintetica'),'erro inesperado');}check85(snapshot85($db)===$before,'rollback '.$op);check85(!$db->inTransaction(),'transacao aberta '.$op);}
$db=db85();$db->exec('CREATE TABLE externo (v TEXT)');$db->beginTransaction();$db->exec("INSERT INTO externo VALUES ('preservado')");fail85($db);$svc=new PessoasService($db);try{$svc->addVinculoInstituicao('p',['instituicao_id'=>'i1','profissao'=>'Medico']);throw new RuntimeException('faltou falha savepoint');}catch(PDOException $e){}check85($db->inTransaction(),'transacao externa fechada');check85((int)$db->query('SELECT COUNT(*) FROM externo')->fetchColumn()===1,'escrita externa perdida');check85((int)$db->query('SELECT COUNT(*) FROM partes_instituicoes')->fetchColumn()===0,'vinculo nao revertido');$db->rollBack();
$db=db85();$svc=new PessoasService($db);$id=$svc->addVinculoInstituicao('p',['instituicao_id'=>'i1','profissao'=>'Medico']);check85($id!=='','sem id');check85($db->query("SELECT profissao FROM partes WHERE id='p'")->fetchColumn()==='Medico','profissao ausente');check85($svc->updateVinculoInstituicao($id,['cargo_funcao'=>'Teste']),'update falhou');check85($svc->deleteVinculoInstituicao($id),'delete falhou');check85(!$svc->deleteVinculoInstituicao($id),'delete repetido');$db=db85();$db->exec("UPDATE partes SET profissao='Medico' WHERE id='p'");$db->exec("INSERT INTO partes_instituicoes VALUES ('v1','p','i1',NULL,'Outra',NULL,'2026-01-01',NULL,NULL,1,NULL,'2026-01-01','2026-01-01')");$db->exec("CREATE TRIGGER falha_vinculo BEFORE UPDATE OF profissao ON partes_instituicoes BEGIN SELECT RAISE(ABORT,'falha reconciliacao'); END");$antes=snapshot85($db);$svc=new PessoasService($db);try{$svc->update('p',['nome_completo'=>'Novo Nome']);throw new RuntimeException('faltou falha update pessoa');}catch(PDOException $e){check85(str_contains($e->getMessage(),'falha reconciliacao'),'erro update pessoa');}check85(snapshot85($db)===$antes,'update pessoa persistiu apos falha');check85(!$db->inTransaction(),'transacao update pessoa aberta');
echo "REI-85 institucional: OK\n";
